:where(.wtyg-map-stand_your_ground) select,:where(.wtyg-map-stand_your_ground) button.btn{background:rgba(255,255,255,.05);color:var(--ink);border:1px solid var(--line);border-radius:4px;padding:2px 6px;font:inherit;font-size:12.5px}
